<?php $pageTitle='Contact RoomShift | Move enquiry';$pageMeta='Contact RoomShift with your move details and a team member can follow up.';include __DIR__.'/includes/header.php';$serviceResult=web_catalog(static fn()=>web_cms()->listServices(['limit'=>100]));include __DIR__.'/includes/navbar.php';$services=$serviceResult['items']??[]; ?><main class="container section-space"><header class="page-heading"><p class="eyebrow">We are here to help</p><h1>Tell us about your move</h1><p>Share a few details and we will receive a real enquiry in our system.</p></header><?php if($GLOBALS['webDataError']): ?><div class="alert alert-warning"><?= e($t('error')) ?></div><?php elseif(!$services): ?><div class="empty-panel">No services are currently available. Please try again later.</div><?php else: ?><form class="contact-panel js-enquiry-form" data-mode="contact" novalidate><div class="row g-3"><div class="col-md-6"><label class="form-label" for="cName">Name</label><input class="form-control" id="cName" name="name" maxlength="120" autocomplete="name" required></div><div class="col-md-6"><label class="form-label" for="cPhone">Phone</label><input class="form-control" id="cPhone" name="phone" type="tel" maxlength="25" autocomplete="tel" required></div><div class="col-md-6"><label class="form-label" for="cEmail">Email (optional)</label><input class="form-control" id="cEmail" name="email" type="email" maxlength="190" autocomplete="email"></div><div class="col-md-6"><label class="form-label" for="cService">Service</label><select class="form-select" id="cService" name="service_id" required><option value="">Choose a service</option><?php foreach($services as $service): ?><option value="<?= (int)$service['id'] ?>"><?= e($service['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label" for="cFrom">Moving from</label><input class="form-control" id="cFrom" name="from_address" maxlength="500" required></div><div class="col-md-6"><label class="form-label" for="cTo">Moving to</label><input class="form-control" id="cTo" name="to_address" maxlength="500" required></div><div class="col-md-3"><label class="form-label" for="cDistance">Distance (km)</label><input class="form-control" id="cDistance" name="distance_km" type="number" min="0" max="10000" step="0.01" required></div><div class="col-md-3"><label class="form-label" for="cFloors">Floors</label><input class="form-control" id="cFloors" name="floors" type="number" min="0" max="100" value="0" required></div><div class="col-md-6"><label class="form-label" for="cMessage">How can we help?</label><textarea class="form-control" id="cMessage" name="message" rows="3" maxlength="3000"></textarea></div></div><button class="btn btn-gold mt-4" type="submit" data-submit><?= e($t('send')) ?></button><div class="mt-3" id="formStatus" role="status" aria-live="polite"></div></form><?php endif; ?></main><?php include __DIR__.'/includes/footer.php';
